"""Internal eight-course SPG assessment map; no invented ParaLearn bindings."""
import json
from pathlib import Path
import sys
ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT))
from schools.exam_blueprints import validate_blueprint
CODES = ['SWP-028', *[f'SWP-{n:03}' for n in range(71, 78)]]


def blueprint():
    rows = json.loads((ROOT / 'production_courseware/release-2026-10-03/course_catalogue.json').read_text(encoding='utf-8'))
    retained = {r['code']: {k: r[k] for k in ('title', 'outcome', 'modules', 'cbt_focus')} for r in rows if r['code'] == 'SWP-028'}
    items = [dict(id=f'SPG8-{code}-MCQ-{n:02}', type='MCQ', marks=1, course_codes=[code], question_binding=None) for code in CODES for n in range(1, 6)]
    short = [
        ([CODES[0], CODES[1]], 'A fictional policy brief calls an announced allowance universal because its legal scope is broad. It counts only completed payments, ignores late payments and unavailable appointments, and recommends expansion without defining the problem or responsible actors. Give five corrections.',
         'Define the problem, intended population and policy actors; distinguish legal entitlement from effective receipt; examine regularity and adequacy against purpose; identify complementary service and access conditions; and recommend a bounded evidence check through an authorised role. Do not determine real eligibility or infer universal reach from a payment count.',
         ['Problem population actors and evidence (028)', 'Entitlement versus effective receipt (071)', 'Regularity and adequacy (071)', 'Complementary access conditions (028/071)', 'Bounded recommendation and authority (028)']),
        ([CODES[2]], 'An invented budget approves 120 units and records 90 spent for a comparable period. A portal posts an undated image, six recommendations are issued, and publicity claims proven theft of 30 units and six completed service improvements. Give five corrections.',
         'Calculate the 30-unit difference and 75 percent spending proportion; seek comparable scope, versions and a reconciliation without alleging theft; distinguish expenditure from service delivery; require usable disclosure and a responsible explanation route; and distinguish recommendations, implemented action and evidenced outcomes with attribution limits.',
         ['Transparent arithmetic', 'Comparable records and no unsupported accusation', 'Spending versus delivery', 'Usable disclosure and response responsibility', 'Recommendation implementation outcome and attribution']),
        ([CODES[3]], 'A fictional travel-support pilot assumes payments create appointments. It opens an unstaffed form, silently changes its target, and claims causal success when completions move from 40 of 50 to 60 of 100 during staffing and eligibility changes. Give five corrections.',
         'Clarify the cost mechanism and appointment-capacity assumption; assign authorised processing and access arrangements; retain the original target and dated justified adaptation; calculate the fall from 80 to 60 percent despite rising counts; and distinguish process and outcome questions from causal attribution amid concurrent changes.',
         ['Mechanism and capacity assumption', 'Delivery authority resources and access', 'Versioned adaptation', 'Counts denominators and proportions', 'Evaluation design and attribution limits']),
        ([CODES[4]], 'A fictional decentralised desk is responsible for hours and materials but controls neither. It offers only an inaccessible form, treats sending a referral as resolution and reports a coordination meeting as universal access. Give five corrections.',
         'Map actual decisions and resources rather than infer powers from a label; identify the responsibility mismatch and authorised clarification role; propose a staffed accessible alternative with understandable reasons; confirm receiving responsibility and follow-up; and distinguish coordination activity from evidenced service outcomes. Do not invent constitutional or statutory powers.',
         ['Actual functional authority and resources', 'Mismatch and mandate clarification', 'Inclusive functioning administration', 'Traceable handover and response', 'Process versus outcome and legal limits']),
        ([CODES[5], CODES[6]], 'An invented options note calls equal payments equitable despite different access costs. It ranks conditional transfers globally by juxtaposing a Brazilian cohort and a US trial, treats repeated online votes as representative, and promises co-decision on an already closed choice. Give five corrections.',
         'Compare practical benefit and remaining access burdens; describe unlike populations, comparisons and designs without a universal transfer ranking; assess institutional incentives without unsupported motive claims; define honest open scope and decision authority; and use accessible methods, acknowledge missing perspectives and explain the disposition of contributions.',
         ['Distribution and adequacy (075)', 'Study design and bounded comparison (075)', 'Institutional mechanism without motive claims (075)', 'Honest influence and authority (076)', 'Inclusive methods representation and feedback (076)']),
        ([CODES[7]], 'A fictional brief treats a 2026 publication as 2026 fieldwork, claims a whole-paper appraisal after reading indexed sections, buys technology before assigning response ownership and calls acceptance and downloads a completed reform. Give five corrections.',
         'Define a bounded decision request and claim record with publication and data dates; disclose inspected evidence and its limits; compare options using common purpose, resources and authority; stage verification, meaningful consultation and a limited reviewable learning step; and separate acceptance, implementation, dissemination and outcomes with versioned review and reconsideration conditions.',
         ['Decision and dated claim record', 'Honest evidence appraisal extent', 'Comparable feasible options', 'Staged authority consultation and learning', 'Accurate status review and reconsideration']),
    ]
    for n, (coverage, prompt, model, criteria) in enumerate(short, 1):
        items.append(dict(id=f'SPG8-SA-{n:02}', type='SHORT_ANSWER', marks=5, course_codes=coverage, prompt=prompt, model_answer=model, rubric=[dict(criterion=x, marks=1, scoring='0 absent/unsafe/unsupported; 1 accurate relevant reasoning applied to the fictional case. Accept equivalent defensible reasoning.') for x in criteria], human_marking_required=True))
    essays = [
        ('Develop a conditional reform brief across all eight SPG courses for an invented social-support service. Legal scope is called universal receipt; an approved budget is called delivered support; a digital portal has no response owner; a district desk lacks resources and decision powers; consultation promises influence over closed choices; and a before-and-after count is called proof of impact. Explain the problem, actors, distribution, options, delivery sequence, evidence limits and accountable review. Use fictional records only.',
         'Integrate policy problem definition, actors, evidence, equity and feasible recommendations (028); entitlement, effective coverage, adequacy and complementary services (071); comparable allocations, execution, usable disclosure and follow-up (072); mechanisms, assumptions, resources, versioned adaptation and evaluation (073); actual institutional authority, inclusive access and traceable coordination (074); distribution, incentives and bounded study comparisons without motive allegations (075); honest scope, accessible input, missing perspectives and reasoned feedback (076); and a concise claim record, options comparison, staged decision and review plan (077). Name authorised decision roles, unresolved resources and observations that would change the recommendation. No classroom output approves expenditure, eligibility or an audit.'),
        ('Critique a fictional claim that a downloaded policy brief has completed a nationally effective reform. The brief compares a US randomised transfer study with a Brazilian cohort as a universal policy ranking, treats Nigerian digital-budget propositions as proven corruption reduction, calls equal payments equal access, treats a coordination meeting as resolved referrals and consultation volume as universal consent, and promises certification from reading slides. Use all eight SPG domains to correct the claim and specify a proportionate next phase.',
         'Separate policy intent from implementation and effects (028); coverage, regularity and adequacy from nominal provision (071); budgets and recommendations from delivery and outcomes (072); process counts, denominators, changing targets and concurrent influences from causal claims (073); institutional labels and sent referrals from actual authority and responses (074); contextual distribution, incentives and design-specific research limits from universal rankings (075); honest influence and feedback from repeated submissions or inferred consent (076); and accepted briefs or downloads from implemented, evaluated reform (077). Propose a verified, resourced and reviewable next step with clear evidence limits. Reading alone earns no badge or certificate: verified course CBT passes, the configured mixed ParaLearn school exam, criterion-level human marking, independent moderation and authorised signatures remain required.'),
    ]
    criteria = [('Policy problem actors and protection coverage adequacy (028/071)', 3), ('Budget evidence transparency and accountable follow-up (072)', 3), ('Implementation assumptions evaluation and institutional authority (073/074)', 3), ('Distribution incentives research limits and meaningful participation (075/076)', 3), ('Coherent brief feasible staged reform and evidence-bounded review (077)', 3)]
    for n, (prompt, model) in enumerate(essays, 1):
        items.append(dict(id=f'SPG8-ESSAY-{n:02}', type='ESSAY', marks=15, course_codes=CODES, prompt=prompt, model_answer=model, human_marking_required=True, rubric=[dict(criterion=x, marks=w, scoring='0 absent/unsafe; 1 relevant limited point; 2 defensible applied reasoning with a gap; 3 coherent contextual reasoning with feasible action, authority and evidence limits. Accept equivalent defensible reasoning.') for x, w in criteria]))
    return dict(status='draft_for_review', school_code='SPG', curriculum_version='SPG-proposed-eight-course-0.1.0', provider='ParaLearn CBT', provider_assessment_id=None, provider_contract_verified=False, required_courses=CODES, programme_target_course_count=8, draft_catalogue_complete=True, curriculum_complete=False, remaining_curriculum_titles=[], retained_course_domains=retained,
        scope_note='Eight-title internal assessment map. Original SWP-028 teaching and CBT remain unchanged. Learning materials may be owner-approved separately; operating authority, provider configuration, human marking and certification remain separate gates.',
        proposed_duration_minutes=210, duration_status='Proposed; accessibility review and learner piloting pending',
        marking_policy=dict(proposed_pass_percent=70, moderation_required=True, ai_only_finalisation=False, rubric_rule='Human criterion-level scores and reasons; independent identified human moderator checks written marks and amendments. Retain response, rubric version, marker, moderator and amendment/appeal history. Accept equivalent defensible reasoning; no automatic professional-competence decision.', appeals='Authorised review retains response, criterion scores, reasons, moderation, dated amendments and outcome.'),
        certification=dict(authorised=False, requirements=['Course badge: approved course plus verified ParaLearn course CBT pass', 'Certificate: all approved school courses plus final mixed ParaLearn exam with human written marking and independent moderation', 'Head of Learning name/signature pending; Founder Prof. Mina Ogbanga; authorised signatures required']), items=items)


if __name__ == '__main__':
    data = blueprint()
    print(validate_blueprint(data))
    (ROOT / 'production_courseware/phase_twelve/spg_batch_01/school_exam_blueprint.json').write_text(json.dumps(data, indent=2, ensure_ascii=False) + '\n', encoding='utf-8')
